mapper.select:
SELECT  FROM jysb_sbxx_001

ORDER BY lrsj DESC, xxzjbh
LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE jysb_sbxx_001 SET
    sbbh=#{sbbh}, sbpp=#{sbpp}, sbxh=#{sbxh}, zblx=#{zblx}, ssgajgjgdm=#{ssgajgjgdm}, cphm=#{cphm},
    jybh=#{jybh}, jyxm=#{jyxm}, jysfz=#{jysfz}, hh=#{hh}, lxdh=#{lxdh}, sbsyzt=#{sbsyzt}, bz=#{bz},
    sjczlxdm=#{sjczlxdm}, sjly=#{sjly}, lrsj=#{lrsj}, lrdwdm=#{lrdwdm}, lrdwmc=#{lrdwmc}, lrrxm=#{lrrxm},
    lrrsfzh=#{lrrsfzh}, xgsj=#{xgsj}, xgdwdm=#{xgdwdm}, xgdwmc=#{xgdwmc}, xgrxm=#{xgrxm}, xgrsfzh=#{xgrsfzh}
WHERE xxzjbh = #{xxzjbh}

mapper.select:
SELECT xxzjbh FROM jysb_sbxx_001
WHERE xxzjbh IN
#{id}

mapper.sql:
SELECT loc.sbbh, loc.jd, loc.wd, loc.sjly
FROM () loc
WHERE loc.jd BETWEEN #{minLng} AND #{maxLng}
  AND loc.wd BETWEEN #{minLat} AND #{maxLat}
